const root = new URL('../', import.meta.url)
const json = async path => JSON.parse(await readFile(new URL(path, root), 'utf8'))
const digest = bytes => createHash('sha256').update(bytes).digest('hex')
const canonical = value => Array.isArray(value) ? value.map(canonical)
  : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value
const digestJson = value => digest(JSON.stringify(canonical(value)))
const own = (value, key) => Object.hasOwn(value, key) ? ['present', value[key]] : ['absent']
const english = (text, label, allowEmpty = false) => {
  assert.equal(typeof text, 'string', label)
  if (!allowEmpty) assert.ok(text.trim(), `${label}: empty English text`)
  assert.doesNotMatch(text, /\p{Script=Han}|[　-〿＀-￯]/u, label)
  assert.doesNotMatch(text, /<\/?[a-z][^>]*>|&(?:#\d+|#x[\da-f]+|[a-z]+);/iu, `${label}: HTML in product text`)
}

