const pointProjection = point => [point.id, point.catalogId, point.position, own(point, 'z'), point.images,
  own(point, 'sourceUrl'), own(point, 'regionType'), own(point, 'regionPoints')]
function mapProjection(map) {
  const copy = { ...map }
  delete copy.mapName
  delete copy.maxNativeZoom
  copy.catalogGroups = map.catalogGroups.map(group => {
    const copy = { ...group }; delete copy.name
    copy.catalogs = group.catalogs.map(catalog => { const copy = { ...catalog }; delete copy.name; return copy })
    return copy
  })
  return copy
}
async function snapshot() {
  const manifest = await json('public/data/manifest.json')
  const collections = new Map(await Promise.all(manifest.maps.map(async map => [map.id, await json(`public${map.pointsUrl}`)])))
  return { manifest, collections }
}

await test('The eight-map snapshot has current metadata, source navigation order and direct region English', async () => {
  const { manifest } = await snapshot()
  assert.equal(validateManifest(manifest), manifest)
  assert.equal(manifest.name, 'pbz map')
  assert.equal(manifest.gameId, '839484')
  assert.ok(expectedSnapshotTimes.includes(manifest.snapshotAt), 'Snapshot timestamp must identify an actual current source snapshot')
  assert.deepEqual(Object.keys(manifest).sort(), ['gameId','maps','name','snapshotAt'])
  assert.deepEqual(manifest.maps.map(map => [map.id, map.mapName]), expectedMaps.map(map => [map.id, map.mapName]))
  assert.doesNotMatch(JSON.stringify(manifest), /\p{Script=Han}/u)
})

for (const expected of expectedMaps) {
  await test(`${expected.mapName}: full ordered identities, geometry, z, media and configured categories`, async () => {
    const { manifest, collections } = await snapshot()
    const map = manifest.maps.find(map => map.id === expected.id)
    assert.ok(map, `Missing required map ${expected.id}`)
    const data = collections.get(map.id)
    const points = validatePoints(map, data)
    assert.equal(map.mapName, expected.mapName)
    assert.equal(data.sourceCount, expected.counts.representations)
    assert.equal(points.length, expected.counts.representations)
    assert.equal(new Set(points.map(point => point.id)).size, expected.counts.canonicalIds)
    assert.equal(new Set(points.map(point => representationKey(map, point))).size, points.length)
    assert.equal(digestJson(mapProjection(map)), expected.structuralMapDigest, 'Every configuration/group/category field and exact presence/type')
    assert.equal(digestJson(points.map(pointProjection)), expected.pointGeometryAndMediaDigest, 'All geometry, z presence, ordered image references and optional source geometry')
    assert.equal(digestJson(points.map(point => [point.catalogId, point.id])), expected.orderedRepresentationDigest)
    assert.equal(digestJson(map.catalogGroups.map(group => group.id)), expected.orderedGroupDigest)
    assert.equal(digestJson(map.catalogGroups.map(group => [group.id, group.catalogs.map(catalog => catalog.id)])), expected.orderedCatalogDigest)
    assert.deepEqual(points.slice(expected.counts.freshRepresentations).map(point => [point.catalogId, point.id]), expected.retainedTuples)
    assert.equal(points.reduce((n, point) => n + point.images.length, 0), expected.counts.imageEntries)
    assert.equal(map.catalogGroups.length, expected.counts.groups)
    assert.deepEqual(map.center, expected.center)
    for (const key of ['minZoom','maxZoom','defaultZoom']) assert.equal(map[key], expected[key])
    assert.equal(map.maxNativeZoom ?? map.maxZoom, expected.maxNativeZoom)
    assert.equal(map.tileSize, 256)
    for (const [key, value] of Object.entries(expected.configuration)) assert.deepEqual(own(map, key), ['present', value], `${map.id}/${key}`)
    const catalogs = allCatalogs(map)
    assert.equal(catalogs.length, expected.counts.categories)
    assert.deepEqual(catalogs.filter(catalog => !catalog.defaultSelected).map(catalog => catalog.id), expected.defaultUnselectedIds)
    assert.ok(isLocalResource(map.tileUrl)); assert.ok(isLocalResource(map.pointsUrl))
    english(map.mapName, `${map.id}/mapName`)
    for (const group of map.catalogGroups) {
      english(group.name, `${map.id}/${group.id}`)
      for (const catalog of group.catalogs) {
        english(catalog.name, `${map.id}/${catalog.id}`)
        assert.equal(points.filter(point => point.catalogId === catalog.id).length, catalog.count)
        for (const path of [catalog.iconUrl, catalog.iconSelectedUrl]) if (path !== null) assert.ok(isLocalResource(path))
      }
    }
    const defaults = new Set(defaultCatalogIds(map))
    for (const point of points) {
      assert.ok(catalogs.some(catalog => catalog.id === point.catalogId))
      english(point.name, `${map.id}/${point.catalogId}/${point.id}/name`)
      english(point.description, `${map.id}/${point.catalogId}/${point.id}/description`, true)
      assert.ok(Object.hasOwn(point, 'description'), 'Genuine empty descriptions stay explicit')
      assert.ok(point.images.every(isLocalResource))
      if (!catalogs.find(catalog => catalog.id === point.catalogId).defaultSelected) assert.equal(defaults.has(point.catalogId), false)
    }
    assert.doesNotMatch(JSON.stringify(data), /\p{Script=Han}/u)
  })
}

await test('The full current-plus-retained union keeps every representation and canonical ID separately', async () => {
  const { manifest, collections } = await snapshot()
  const points = [...collections.values()].flatMap(data => data.landmarks)
  assert.equal(points.length, expectedTotals.representations)
  assert.equal(new Set(points.map(point => point.id)).size, expectedTotals.canonicalIds)
  assert.equal(manifest.maps.reduce((n, map) => n + map.catalogGroups.length, 0), expectedTotals.groups)
  assert.equal(manifest.maps.reduce((n, map) => n + allCatalogs(map).length, 0), expectedTotals.categories)
  assert.equal(points.reduce((n, point) => n + point.images.length, 0), expectedTotals.imageEntries)
  for (const expected of expectedMaps) {
    const rows = collections.get(expected.id).landmarks
    assert.equal(rows.length - expected.counts.freshRepresentations, expected.counts.retainedRepresentations)
    for (const [catalogId,id] of expected.retainedTuples) assert.equal(rows.filter(point => point.id === id && point.catalogId === catalogId).length, 1)
  }
})

await test('Every complete owning English field and optional record matches the independent release snapshot', async () => {
  assert.ok(expectedEnglishSnapshot, 'A complete independently frozen release baseline is required; never derive expected hashes from the product')
  const { manifest, collections } = await snapshot()
  assert.equal(expectedEnglishSnapshot.requiredFields, 5668)
  assert.equal(expectedEnglishSnapshot.verifiedFields, 2744)
  assert.equal(expectedEnglishSnapshot.genuineEmptyDescriptions, 742)
  assert.equal(expectedEnglishSnapshot.verifiedFields + expectedEnglishSnapshot.genuineEmptyDescriptions, 3486)
  assert.equal(expectedEnglishSnapshot.provisionalExistingFields, 1741)
  assert.equal(expectedEnglishSnapshot.provisionalNewFields, 441)
  assert.equal(expectedEnglishSnapshot.verifiedFields + expectedEnglishSnapshot.genuineEmptyDescriptions
    + expectedEnglishSnapshot.provisionalExistingFields + expectedEnglishSnapshot.provisionalNewFields, 5668)
  assert.equal(expectedEnglishSnapshot.releaseMissingFields, 0)
  assert.equal(expectedEnglishSnapshot.unresolvedFields, 2182, 'Designated-site full correspondence remains deferred, not accepted')
  assert.equal(expectedEnglishSnapshot.fullSourceCorrespondenceAccepted, false)
  const points = [...collections.values()].flatMap(data => data.landmarks)
  assert.equal(manifest.maps.reduce((count, map) => count + 1 + map.catalogGroups.length + allCatalogs(map).length, 0)
    + points.length * 2, expectedEnglishSnapshot.requiredFields)
  assert.equal(points.filter(point => point.description === '').length, expectedEnglishSnapshot.genuineEmptyDescriptions)
  assert.equal(digestJson(manifest), expectedEnglishSnapshot.completeManifestDigest)
  for (const map of manifest.maps) {
    const data = collections.get(map.id)
    const expected = expectedEnglishSnapshot.maps.find(row => row.id === map.id)
    assert.ok(expected)
    assert.equal(digestJson(data), expected.completeCollectionDigest, 'Every point field including optional fields and complete array order')
    assert.equal(digestJson(data.landmarks.map(point => [point.catalogId,point.id,point.name,point.description])), expected.owningEnglishDigest)
    assert.equal(data.landmarks.filter(point => point.description.trim()).length, expected.nonemptyDescriptions)
    assert.equal(data.landmarks.filter(point => !point.description.trim()).length, expected.emptyDescriptions)
  }
})

await test('The original terminology and Shadow Warden choice retain exact release field and search identities', async () => {
  assert.ok(expectedEnglishSnapshot?.terminology, 'Term occurrences must be independently frozen with the release selection, not inferred from product')
  const { manifest, collections } = await snapshot()
  assert.deepEqual(expectedEnglishSnapshot.terminology.map(row => row.term), [
    'Bagua Pavilion', 'Bashpole', "Quick Hand's Request", 'Flameward',
    'Shieldbreaker Talisman', 'The Four Serpent Houses', 'Shadow Warden',
  ])
  // These release occurrences include provisional fields; they do not confer source acceptance.
  for (const { term, occurrences, searchRepresentations } of expectedEnglishSnapshot.terminology) {
    assert.ok(occurrences.length)
    for (const [mapId, catalogId, id, field] of occurrences) {
      const point = collections.get(mapId).landmarks.find(point => point.id === id && point.catalogId === catalogId)
      assert.ok(point?.[field].includes(term), `${mapId}/${catalogId}/${id}/${field}`)
    }
    const results = searchLandmarks(manifest.maps.map(config => ({ config, landmarks: collections.get(config.id).landmarks })), term)
    assert.deepEqual([...results.title,...results.description].map(result => [result.mapId,result.catalogId,result.point.id]), searchRepresentations)
  }
  assert.ok(expectedEnglishSnapshot.shadowWardenFields.length)
  for (const [mapId, catalogId, id, field, english] of expectedEnglishSnapshot.shadowWardenFields) {
    const point = collections.get(mapId).landmarks.find(point => point.id === id && point.catalogId === catalogId)
    assert.equal(point[field], english)
    assert.match(point[field], /Shadow Warden/)
  }
})

await test('The two real 913193 category representations keep distinct owning text, geometry, search and shared completion', async () => {
  const { manifest, collections } = await snapshot()
  const config = manifest.maps.find(map => map.id === '255')
  const points = collections.get('255').landmarks
  const rows = points.filter(point => point.id === '913193')
  assert.deepEqual(rows.map(point => [point.catalogId,point.position,point.z]), [
    ['10144',[-0.7437984914378148,1.0149717183482778],400],
    ['10157',[-0.743648930242216,1.0210237672753948],400],
  ])
  assert.notEqual(rows[0].name,rows[1].name)
  assert.notEqual(rows[0].description,rows[1].description)
  assert.notEqual(representationKey(config,rows[0]),representationKey(config,rows[1]))
  for (const row of rows) {
    const results=searchLandmarks([{config,landmarks:points}],row.name)
    assert.ok(results.title.some(result=>result.catalogId===row.catalogId&&result.point===row))
    assert.equal(points.filter(point=>point.catalogId===row.catalogId).length,allCatalogs(config).find(catalog=>catalog.id===row.catalogId).count)
  }
  assert.deepEqual(filterLandmarks(rows,{catalogIds:rows.map(point=>point.catalogId),completionFilter:'completed',completedIds:new Set(['913193'])}),rows)
  assert.deepEqual(filterLandmarks(rows,{catalogIds:rows.map(point=>point.catalogId),completionFilter:'incomplete',completedIds:new Set(['913193'])}),[])
  const duplicate=structuredClone(collections.get('255'));duplicate.landmarks.push(structuredClone(rows[0]));duplicate.sourceCount++
  assert.throws(()=>validatePoints(config,duplicate),/incomplete or invalid/)
})

async function ordinaryLocalFile(logical) {
  assert.ok(isLocalResource(logical))
  const file=new URL(`public${logical}`,root)
  const info=await lstat(file)
  assert.ok(info.isFile()&&!info.isSymbolicLink()&&info.size>0,logical)
  assert.equal(info.nlink,1,'Product media must be independent ordinary files, not hardlinks to private evidence')
  assert.equal(await realpath(file),fileURLToPath(file),'No ancestor resource symlink may escape into private evidence')
  const bytes=await readFile(file)
  return [logical,digest(bytes),bytes.length]
}
function tileRange(bounds,zoom) {
  const n=2**zoom
  const x=lon=>(lon+180)/360*n
  const y=lat=>(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n
  return [Math.max(0,Math.floor(x(bounds[0]))),Math.min(n-1,Math.ceil(x(bounds[2]))-1),Math.max(0,Math.floor(y(bounds[3]))),Math.min(n-1,Math.ceil(y(bounds[1]))-1)]
}
await test('All configured icons, complete native XYZ levels and ordered images are exact ordinary local files', async () => {
  const { manifest, collections }=await snapshot()
  const references=new Set(),resources=new Set()
  for(const map of manifest.maps) {
    for(const catalog of allCatalogs(map)) for(const resource of [catalog.iconUrl,catalog.iconSelectedUrl]) if(resource) references.add(resource)
    for(const point of collections.get(map.id).landmarks) for(const resource of point.images) references.add(resource)
    const expected=expectedMaps.find(row=>row.id===map.id)
    for(let z=map.minZoom;z<=expected.maxNativeZoom;z++) {
      const [x0,x1,y0,y1]=tileRange(map.bounds,z)
      for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++) resources.add(map.tileUrl.replace('{z}',z).replace('{x}',x).replace('{y}',y))
    }
  }
  assert.equal(digestJson([...references].sort()),expectedMedia.referenceDigest)
  for(const resource of references) resources.add(resource)
  assert.equal(resources.size,expectedMedia.count)
  const rows=[]
  for(const logical of [...resources].sort()) rows.push(await ordinaryLocalFile(logical))
  assert.equal(digestJson(rows),expectedMedia.byteDigest,'Every native tile/icon/image byte SHA and size remains exact')
})

await test('All recovered map and control media match the independent original-byte inventory without a data fallback', async () => {
  const logicalPaths = []
  async function collect(logical) {
    const directory = new URL(`public${logical}/`, root)
    const info = await lstat(directory)
    assert.ok(info.isDirectory() && !info.isSymbolicLink(), logical)
    assert.equal(await realpath(directory), fileURLToPath(directory).replace(/\/$/, ''), 'Media directories must not alias private evidence')
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      const path = `${logical}/${entry.name}`
      if (entry.isDirectory()) await collect(path)
      else {
        assert.ok(entry.isFile() && !entry.isSymbolicLink(), path)
        logicalPaths.push(path)
      }
    }
  }
  await collect('/assets')
  assert.equal(logicalPaths.length, expectedMedia.allFiles)
  const rows = []
  for (const logical of logicalPaths.sort()) rows.push(await ordinaryLocalFile(logical))
  assert.equal(rows.reduce((bytes, row) => bytes + row[2], 0), expectedMedia.allBytes)
  assert.equal(digestJson(rows), expectedMedia.allByteDigest, 'Every recovered map/retained/cover/control path, byte SHA and length is independently pinned')
})

